// --- Detect File Type + Content Analyzer ---
// Purpose: Segregate uploaded files based on file type, doc type, and content composition.

const newItems = [];

// --- Lightweight analyzer for text/image detection ---
async function analyzeDocumentContent(fileType, base64Data) {
  const buffer = Buffer.from(base64Data, 'base64');
  let containsText = false;
  let containsImages = false;

  // Read only part of file to avoid memory overload
  const sampleText = buffer.toString('utf8', 0, 50000);

  switch (fileType) {
    case 'pdf':
      if (/BT|ET|\/Font|\/Text/i.test(sampleText)) containsText = true;
      if (/\/Image|\/Subtype\s*\/Image/i.test(sampleText)) containsImages = true;
      break;

    case 'doc':
      // DOCX/DOC internal relationships (text & images)
      if (/<w:t>.*?<\/w:t>/i.test(sampleText)) containsText = true;
      if (/word\/media\//i.test(sampleText)) containsImages = true;
      break;

    case 'ppt':
      if (/<a:t>.*?<\/a:t>/i.test(sampleText)) containsText = true;
      if (/ppt\/media\//i.test(sampleText)) containsImages = true;
      break;
  }

  // Fallback: detect if it’s probably text
  if (!containsText && !containsImages) {
    const textChars = sampleText.replace(/[^A-Za-z0-9\s]/g, '');
    if (textChars.length > 50) containsText = true;
  }

  return { containsText, containsImages };
}

// --- Main logic (must be async wrapper in n8n Code Node) ---
return (async () => {
  for (const item of items) {
    const binaries = item.binary || {};

    for (const [key, bin] of Object.entries(binaries)) {
      if (!bin?.data) continue;

      const fileName = (bin.fileName || key || '').toString();
      const mime = (bin.mimeType || '').toLowerCase();
      const lower = fileName.toLowerCase();

      let fileType = 'unknown';
      let docType = 'unknown';
      let containsText = false;
      let containsImages = false;

      // --- Basic file type detection ---
      if (mime.startsWith('image/') || /\.(png|jpg|jpeg|gif|svg|webp)$/i.test(lower)) {
        fileType = 'image';
        containsImages = true;
      } else if (/\.(txt)$/i.test(lower)) {
        fileType = 'text';
        containsText = true;
      } else if (/\.(pdf)$/i.test(lower)) {
        fileType = 'pdf';
      } else if (/\.(docx|doc)$/i.test(lower)) {
        fileType = 'doc';
      } else if (/\.(pptx|ppt)$/i.test(lower)) {
        fileType = 'ppt';
      }

      // --- docType classification ---
      if (/brd/i.test(fileName)) docType = 'brd';
      else if (/frd/i.test(fileName)) docType = 'frd';
      else if (/hld/i.test(fileName)) docType = 'hld';
      else if (/lld/i.test(fileName)) docType = 'lld';
      else if (/transcript|grooming|meeting|discussion/i.test(fileName)) docType = 'transcript';
      else if (fileType === 'ppt') docType = 'supporting';
      else if (fileType === 'image') docType = 'image';
      else docType = 'unknown';

      // --- Analyze for content composition ---
      if (['pdf', 'doc', 'ppt'].includes(fileType)) {
        const result = await analyzeDocumentContent(fileType, bin.data);
        containsText = result.containsText;
        containsImages = result.containsImages;
      }

      // --- Determine contentType ---
      let contentType = 'unknown';
      if (containsText && !containsImages) contentType = 'plain-text';
      else if (!containsText && containsImages) contentType = 'image-only';
      else if (containsText && containsImages) contentType = 'mixed';

      console.log(`Analyzed ${fileName} → ${contentType}`);

      // --- Push result ---
      newItems.push({
        json: {
          fileName,
          fileType,
          docType,
          containsText,
          containsImages,
          contentType,
          fileKey: key,
        },
        binary: {
          [key]: bin,
        },
      });
    }
  }

  return newItems;
})();

/**
 * Normalize text extracted from Gemini "Analyze an Image" or OpenAI Vision.
 * Automatically detects Gemini structure containing:
 *   item.content.parts[0].text
 */

const newItems = [];

for (const outer of items) {
  const meta = outer.json || {};

  // Normalize message array (handles OpenAI + Gemini formats)
  const messageArray = Array.isArray(meta)
    ? meta
    : meta.content?.parts
      ? [meta]  // Gemini response case
      : Array.isArray(outer)
        ? outer
        : [outer];

  for (const msg of messageArray) {
    let text = '';

    // -------------------------------
    // 1. Extract text from GEMINI format
    // -------------------------------
    if (
      msg?.content?.parts &&
      Array.isArray(msg.content.parts) &&
      msg.content.parts[0]?.text
    ) {
      text = msg.content.parts[0].text;
    }

    // -------------------------------
    // 2. Extract text from OpenAI Vision formats
    // -------------------------------
    else if (msg?.json?.text) {
      text = msg.json.text;
    } 
    else if (msg?.text) {
      text = msg.text;
    } 
    else if (msg?.content && Array.isArray(msg.content)) {
      const contentText = msg.content.find(c => c.type === 'output_text');
      if (contentText?.text) text = contentText.text;
    } 
    else if (typeof msg === 'string') {
      text = msg;
    }

    if (typeof text !== 'string') text = String(text || '');

    // -------------------------------
    // 3. Cleanup Processing
    // -------------------------------
    text = text
      .replace(/\r\n/g, '\n')
      .replace(/[ \t]+/g, ' ')
      .replace(/\n{2,}/g, '\n\n')
      .replace(/\f/g, ' ')
      .trim();

    // Remove repeated/noisy lines
    const lines = text.split('\n');
    const seen = new Set();
    const filtered = lines.filter(line => {
      const l = line.trim().toLowerCase();
      if (!l || seen.has(l)) return false;
      seen.add(l);

      // Drop auto-labeled noise
      if (/^(diagram|figure|screenshot|ui|image|architecture|flow|mockup)/i.test(l)) return false;
      return true;
    });
    text = filtered.join('\n').trim();

    // Normalize punctuation
    text = text
      .replace(/\s+([.,;:!?])/g, '$1')
      .replace(/([.,;:!?])([^\s])/g, '$1 $2')
      .replace(/\s{2,}/g, ' ');

    // Capitalize sentence starts
    text = text.replace(/(^|[.!?]\s+)([a-z])/g, (_, prefix, c) => prefix + c.toUpperCase());

    // Truncate extremely long structured dumps
    if (text.length > 5000) {
      text = text.slice(0, 5000) + '... [truncated for processing]';
    }

    // -------------------------------
    // 4. Attach metadata from “Switch - Find Extractor”
    // -------------------------------

    const extractor = $('Switch - Find Extractor').first().json;

    const normalized = {
      normalizedVisionText: text,
      source: 'Gemini-Vision',
      cleaningStatus: 'normalized',
      fileName: extractor.fileName || 'Unknown_File',
      fileType: extractor.fileType || 'Unknown',
      docType: extractor.docType || 'Unknown',
      requiresVision: extractor.requiresVision ?? true,
      contentType: extractor.contentType || 'image'
    };

    newItems.push({ json: normalized });
  }
}

return newItems;

// Normalize and tag each document extract with type headers
const cleanedDocs = [];

for (const item of items) {
  const d = item.json || {};
  const text = d.text || "";

  // Identify document type
  const type =
    d.fileName?.match(/BRD|FRD|HLD|LLD/i)?.[0]?.toUpperCase() || "DOCUMENT";

  // Basic cleaning: remove extra spaces, page numbers, headers/footers
  const cleaned = text
    .replace(/\bPage\s+\d+\b/gi, "") // remove page numbers
    .replace(/\n\s*\n\s*\n+/g, "\n\n") // collapse multiple newlines
    .replace(/[ \t]{2,}/g, " ") // remove excessive spaces
    .trim();

  cleanedDocs.push({
    json: {
      sourceName: d.fileName || "Unknown Document",
      sourceType: type,
      text: `### Source: ${type}\n${cleaned}`,
      timestamp: new Date().toISOString(),
    },
  });
}

return cleanedDocs;

return $input.all().map(item => {
  // Just ensure it has a single binary key called "data"
  const binaries = item.binary || {};
  const keys = Object.keys(binaries);
  if (keys.length === 0) return item;

  const firstKey = keys[0];
  const bin = binaries[firstKey];
  // Keep structure intact
  return {
    json: item.json,
    binary: { data: bin },
  };
});

let output = [];

for (const item of items) {

  const out = item.json.stdout;
  if (!out) throw new Error("No stdout returned from Python script.");

  let parsed;
  try {
    parsed = JSON.parse(out);
  } catch (err) {
    throw new Error("Invalid JSON in stdout: " + out);
  }

  const arr = Array.isArray(parsed) ? parsed : [parsed];

  // Main PDF entry (not extracted images)
  const docInfo = arr.find(p => !p.isExtractedImage) || arr[0];

  //
  // 1️⃣  Create MAIN PDF ITEM
  //
  const pdfItem = {
    json: {
      ...item.json,
      parsedRaw: arr,
      parsedContainsImage: docInfo.containsImage,
      parsedImageCount: docInfo.imageCount,
      parsedImageFiles: docInfo.imageFiles
    },
    binary: item.binary || {}
  };

  output.push(pdfItem);

  //
  // 2️⃣  If extracted images exist → create separate items
  //
  const extractedImages = arr.filter(p => p.isExtractedImage);

  for (const img of extractedImages) {
    const imgItem = {
      json: {
        sourceDoc: img.sourceDoc || item.json.fileName,
        imageFile: img.file,
        isExtractedImage: true,
        imageCount: img.imageCount,
        imageFiles: img.imageFiles
      },
      binary: {}     // keep empty now — can attach actual binary later if required
    };

    output.push(imgItem);
  }
}

return output;

