  }
}];

// Merge all normalized document + transcript text into one large context
let allTexts = [];

for (const item of items) {
  const src = item.json.sourceType || item.json.sourceName || "Unknown Source";
  const txt = item.json.text ||item.json.normalizedVisionText || "";

  if (txt.trim()) {
    allTexts.push(txt); // already has Source: tags
  }
}

// Optional: Insert separator between sources
const merged = allTexts.join("\n\n---\n\n");

return [{
  json: {
    mergedContext: merged,
    contextCount: allTexts.length
  }
}];

/**
 * Clean, normalize, deduplicate and chunk the merged context
 * to prevent:
 * - duplicated LLM output
 * - undefined blocks
 * - hallucinated subsections
 * - excessive tokens
 * - repeated paragraphs
 */
const input = $json.mergedContext || "";

// 1. Remove garbage tokens
let cleaned = input
  .replace(/undefined/gi, "")
  .replace(/```+/g, "")
  .replace(/\\page/g, "")
  .replace(/\t+/g, " ")
  .replace(/\s{2,}/g, " ")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

// 2. Normalize heading structure (LLM loves this)
cleaned = cleaned.replace(/^#+\s*/gm, "");

// 3. Split into paragraphs
let paragraphs = cleaned
  .split(/\n{2,}/)
  .map(p => p.trim())
  .filter(p => p.length > 0);

// 4. Deduplicate paragraphs based on content fingerprint
const seen = new Set();
let unique = [];

for (let p of paragraphs) {
  const key = p.toLowerCase().replace(/[^a-z0-9]/g, "");
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(p);
  }
}

// 5. Rejoin cleaned content
let finalText = unique.join("\n\n");

// 6. Hard token guard (max chunk size ~12k chars)
const maxSize = 12000;
let chunks = [];

for (let i = 0; i < finalText.length; i += maxSize) {
  chunks.push(finalText.substring(i, i + maxSize));
}

return [
  {
    json: {
      cleanedContext: finalText,
      chunks,
      chunkCount: chunks.length
    }
  }
];
